<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <cstdio>
#include <cstring>
#include <algorithm>
#define REP(i,a,b) for(int i=a;i<=b;i++)
#define REV(i,a,b) for(int i=a;i>=b;i--)
using namespace std;

typedef long long ll;

const int MAXN=262144;

int L,n,k,Mo,len,bit[20],fac[MAXN],inv[MAXN],cnt[MAXN],g[20][MAXN],f[20][MAXN],h[20],p[20];

int qpow(int base,int exp) {
	int res=1;
	while(exp) {
		if (exp&1) res=(ll)res*base%Mo;
		base=(ll)base*base%Mo;
		exp>>=1;
	}
	return res;
}

void add_mod(int &x,int y) {x=x+y>=Mo?x+y-Mo:x+y;}
void sub_mod(int &x,int y) {x=x-y<0?x-y+Mo:x-y;}
void fast_transform(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				add_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}
void inverse_transform(int *a,int len) {
	for(int i=1;i<len;i<<=1) {
		for(int j=0;j<len;j+=i<<1) {
			for(int k=0;k<i;k++) {
				sub_mod(a[j+k+i],a[j+k]);
			}
		}
	}
}

void compute_ln(int *a,int *b,int n) {
	b[0]=0;
	REP(i,1,n) {
		b[i]=(ll)a[i]*i%Mo;
		REP(j,1,i-1) {
			b[i]+=(Mo-(ll)b[j]*a[i-j]%Mo*j)%Mo;
		}
		b[i]=(ll)b[i]*qpow(i,Mo-2)%Mo;
	}
}

void compute_exp(int *a,int *b,int n) {
	b[0]=1;
	REP(i,1,n) {
		b[i]=0;
		REP(j,1,i) {
			b[i]+=(ll)a[j]*b[i-j]%Mo*j%Mo;
		}
		b[i]=(ll)b[i]*qpow(i,Mo-2)%Mo;
	}
}

int main() {
	scanf("%d%d%d",&L,&k,&Mo);
	int total=pow(k,L);
	if (L&1) {
		printf("%d\n",total);
		return 0;
	}
	fac[0]=1; REP(i,1,L) fac[i]=(ll)fac[i-1]*i%Mo;
	inv[L]=qpow(fac[L],Mo-2); REV(i,L-1,0) inv[i]=(ll)inv[i+1]*(i+1)%Mo;
	REP(s,1,L) cnt[s]=cnt[s^(s&-s)]+1;
	REP(i,0,18) if (L>>i&1) bit[++n]=1<<i;
	len=1<<n;
	REP(i,0,len-1) {
		int s=0;
		REP(j,1,n) if (i>>(j-1)&1) s+=bit[j];
		g[cnt[i]][i]=inv[s];
	}
	fast_transform(g[0],len);
	fast_transform(g[1],len);
	fast_transform(g[2],len);
	REP(s,0,len-1) {
		REP(i,0,n) h[i]=g[i][s];
		get_ln(h,p,n);
		REP(i,0,n) p[i]=(ll)p[i]*k%Mo;
		get_exp(p,h,n);
		REP(i,0,n) f[i][s]=h[i];
	}
	inverse_transform(f[n],len);
	int answer=(ll)f[n][len-1]*fac[L]%Mo;
	answer=(total-answer+Mo)%Mo;
	printf("%d\n",answer);
	return 0;
}
